import 'dart:async';

import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class NewsListPage extends StatefulWidget {
  const NewsListPage({super.key});

  @override
  State<NewsListPage> createState() => _NewsListPageState();
}

class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
  List<NewsModel> _newsItems = const [];

  static final _tween = Tween<double>(begin: 0.25, end: 1);

  late final AnimationController _scaleController;
  late final Animation<double> _scaleAnimation;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _loadCacheThenNetwork();
  }

  @override
  void dispose() {
    _scaleController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _scaleController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 200),
    );
    _scaleAnimation = _tween.animate(_scaleController);
  }

  /// Загрузка из кэша (мгновенно) → затем фоновая загрузка из сети.
  void _loadCacheThenNetwork() {
    final newsRepository = context.read<NewsRepository>();

    // Шаг 1: мгновенный кэш (БД)
    unawaited(
      newsRepository.loadNewsFeed(const NewsFeedFilter.all).then((cached) {
        if (!mounted) return;
        setState(() => _newsItems = cached);
        _scaleController.forward();
      }),
    );

    // Шаг 2: фоновое обновление из сети (сеть + запись в кэш)
    unawaited(
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)).then((fresh) {
        if (!mounted) return;
        setState(() => _newsItems = fresh);
      }),
    );
  }

  @override
  Widget build(BuildContext context) => Scaffold(
        appBar: AppBar(title: Text(context.loc.news)),
        body: ScaleTransition(
          scale: _scaleAnimation,
          child: ListView.builder(
            itemCount: _newsItems.length,
            itemBuilder: (BuildContext context, int index) {
              final NewsModel news = _newsItems[index];

              return Padding(
                key: ValueKey(news.link),
                padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
                child: NewsCard(model: news),
              );
            },
            padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
          ),
        ),
      );
}

